package com.aditya.fefo.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="stock_movements") public class StockMovement { @Id private UUID id; @Column(name="product_id") private UUID productId; @Column(name="batch_id") private UUID batchId; @Column(name="reservation_id") private UUID reservationId; @Column(name="movement_type") private String movementType; private long quantity; @Column(name="actor_id") private UUID actorId; private String reason; @Column(name="created_at") private Instant createdAt; protected StockMovement(){} public StockMovement(UUID productId,UUID batchId,UUID reservationId,MovementType type,long quantity,UUID actorId,String reason){this.id=UUID.randomUUID();this.productId=productId;this.batchId=batchId;this.reservationId=reservationId;this.movementType=type.name();this.quantity=quantity;this.actorId=actorId;this.reason=reason;this.createdAt=Instant.now();} }
